// ===========================================================================
//  CK·11 RADAR THỊ TRƯỜNG - quét rổ rộng (VN30 + thanh khoản cao), tự nổi lên
//  TOP biến động NGOÀI watchlist. Chỉ PHÁT HIỆN, không khuyến nghị mua.
// ===========================================================================
const UNIVERSE = [
  'ACB','BCM','BID','BVH','CTG','FPT','GAS','GVR','HDB','HPG','MBB','MSN','MWG','PLX','POW','SAB','SHB','SSB','SSI','STB','TCB','TPB','VCB','VHM','VIB','VIC','VJC','VNM','VPB','VRE',
  'DGC','DXG','KBC','GEX','HSG','NKG','DIG','PDR','VND','VIX','FRT','PNJ','REE','KDH','NLG','VCI','HCM','DCM','DPM','IDC','SZC','GMD','HAH','DBC'
];
const TIER = { VNM:'🟢A',VCB:'🟢A',FPT:'🟢A',PNJ:'🟢A',MWG:'🟢A',REE:'🟢A',GAS:'🟢A',ACB:'🟢A',SAB:'🟢A',
  HPG:'🟡B',SSI:'🟡B',KBC:'🟡B',DGC:'🟡B',MBB:'🟡B',TCB:'🟡B',FRT:'🟡B',HDB:'🟡B',GMD:'🟡B',PLX:'🟡B',
  GEX:'🔴C',DXG:'🔴C',HSG:'🔴C',VND:'🔴C',DIG:'🔴C',PDR:'🔴C',NKG:'🔴C',VIX:'🔴C',DBC:'🔴C',SZC:'🔴C' };
const CORE = new Set(['VNM','FPT','HPG','MWG','VCB','SSI','DGC','VND','MBB','STB']);
const mark = (t) => (CORE.has(t) ? '🎯' : '') + (TIER[t] || '');

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const hBar = { 'User-Agent': UA, 'Accept': '*/*' };
const hFin = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };
const to = Math.floor(Date.now() / 1000), from = to - 60 * 60 * 24 * 45;

const normBars = (r) => { if (!r || !Array.isArray(r.c) || !r.c.length) return r; const last = r.c[r.c.length - 1]; if (last > 0 && last < 1000) for (const k of ['c', 'o', 'h', 'l']) if (Array.isArray(r[k])) r[k] = r[k].map(x => x * 1000); return r; };
const fetchBars = async (t) => {
  try { const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock', qs: { symbol: t, from, to, resolution: '1D' }, headers: hBar, json: true, timeout: 12000 }); if (r && Array.isArray(r.c) && r.c.length) return normBars(r); } catch (e) {}
  try { const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://dchart-api.vndirect.com.vn/dchart/history', qs: { symbol: t, resolution: 'D', from, to }, headers: { ...hBar, Referer: 'https://dchart.vndirect.com.vn/' }, json: true, timeout: 12000 }); if (r && Array.isArray(r.c) && r.c.length) return normBars(r); } catch (e) {}
  return null;
};
const fetchFlow = async (t) => { try { const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + t + '&size=5&sort=tradingDate:desc', headers: hFin, json: true, timeout: 12000 }); return ((r && r.data) || []).map(x => (x.netVal || 0) / 1e9); } catch (e) { return []; } };

// quét song song theo lô để nhanh
const mapLimit = async (items, limit, fn) => { const out = []; let i = 0; const work = async () => { while (i < items.length) { const idx = i++; out[idx] = await fn(items[idx]); } }; await Promise.all(Array.from({ length: limit }, work)); return out; };

const scan = async (t) => {
  try {
    const bars = await fetchBars(t);
    if (!bars || !bars.c || bars.c.length < 6) return null;
    const n = bars.c.length, close = bars.c[n - 1], close5 = bars.c[n - 6];
    const pct5 = close5 ? (close - close5) / close5 * 100 : 0;
    const vols = bars.v || []; let volSpike = 0;
    if (vols.length >= 6) { const ref = vols.slice(Math.max(0, n - 21), n - 1); const avg = ref.reduce((a, b) => a + b, 0) / (ref.length || 1); volSpike = avg ? vols[n - 1] / avg : 0; }
    const nets = await fetchFlow(t);
    const net5 = nets.reduce((a, b) => a + b, 0);
    return { t, pct5, net5, volSpike };
  } catch (e) { return null; }
};

const results = (await mapLimit(UNIVERSE, 8, scan)).filter(Boolean);
const scanned = results.length;

const fmtTy = (v) => (v >= 0 ? '+' : '') + v.toFixed(0) + ' tỷ';
const fmtPc = (v) => (v >= 0 ? '+' : '') + v.toFixed(1) + '%';
const line = (rows, val) => rows.map(r => '• ' + r.t + (mark(r.t) ? ' ' + mark(r.t) : '') + '  ' + val(r)).join('\n');

const byNet = [...results].sort((a, b) => b.net5 - a.net5);
const gom = byNet.filter(r => r.net5 > 1).slice(0, 6);
const xa = [...byNet].reverse().filter(r => r.net5 < -1).slice(0, 6);
const byPct = [...results].sort((a, b) => b.pct5 - a.pct5);
const up = byPct.slice(0, 6);
const down = [...byPct].reverse().slice(0, 6);
const vol = [...results].filter(r => r.volSpike >= 2).sort((a, b) => b.volSpike - a.volSpike).slice(0, 6);

// mã ngoài watchlist đáng để ý: nổi bật ở gom mạnh hoặc giảm sâu, không thuộc CORE
const candidates = [...new Set([...gom.slice(0, 4), ...down.slice(0, 3)].map(r => r.t))].filter(t => !CORE.has(t)).slice(0, 6);

const today = new Date().toLocaleDateString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', day: 'numeric', month: 'numeric', year: 'numeric' });
const L = [];
const _hr = parseInt(new Date().toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh', hour: '2-digit', hour12: false }));
const _sess = _hr < 12 ? 'trước phiên' : 'sau phiên';
L.push('📡 *RADAR THỊ TRƯỜNG* (' + _sess + ') — ' + today);
L.push('_Quét ' + scanned + '/' + UNIVERSE.length + ' mã (VN30 + thanh khoản cao) · 🎯=watchlist · 🟢A/🟡B/🔴C=bậc rủi ro_');
if (!scanned) { L.push(''); L.push('🔴 Không lấy được dữ liệu (API có thể đang lỗi). Thử lại phiên sau.'); return [{ json: { message: L.join('\n') } }]; }
L.push('');
L.push('🟢 *NGOẠI GOM MẠNH* (5 phiên)'); L.push(gom.length ? line(gom, r => fmtTy(r.net5)) : '_không có_');
L.push(''); L.push('🔴 *NGOẠI XẢ MẠNH* (5 phiên)'); L.push(xa.length ? line(xa, r => fmtTy(r.net5)) : '_không có_');
L.push(''); L.push('🚀 *TĂNG GIÁ* (5 phiên)'); L.push(line(up, r => fmtPc(r.pct5)));
L.push(''); L.push('📉 *GIẢM SÂU* (5 phiên — cơ hội mean-reversion?)'); L.push(line(down, r => fmtPc(r.pct5)));
if (vol.length) { L.push(''); L.push('🔥 *KHỐI LƯỢNG ĐỘT BIẾN* (≥2× TB20)'); L.push(line(vol, r => '×' + r.volSpike.toFixed(1) + ' · ' + fmtPc(r.pct5))); }
L.push('');
if (candidates.length) L.push('💡 *Ngoài watchlist đáng /check:* ' + candidates.join(', '));
L.push('_Radar chỉ PHÁT HIỆN, không phải khuyến nghị. Gõ /check rồi /sâu trước khi quyết._');

return [{ json: { message: L.join('\n') } }];
